import React, { useState } from 'react';
import { Card, Upload, Button, Table, Tag, Input, Space, message, Modal } from 'antd';
import { InboxOutlined, LinkOutlined, DeleteOutlined, FileTextOutlined } from '@ant-design/icons';
import type { UploadProps } from 'antd';

const { Dragger } = Upload;

interface DataFile {
  key: string;
  name: string;
  type: string;
  size: string;
  source: 'Local' | 'URL';
  status: 'Active' | 'Inactive';
  date: string;
}

const DataManagement: React.FC = () => {
  const [dataFiles, setDataFiles] = useState<DataFile[]>([
    { key: '1', name: 'jinhua_weather_2023.csv', type: 'CSV', size: '2.4 MB', source: 'Local', status: 'Active', date: '2023-10-01' },
    { key: '2', name: 'realtime_api_config.json', type: 'JSON', size: '12 KB', source: 'URL', status: 'Active', date: '2023-10-05' },
  ]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [urlInput, setUrlInput] = useState('');

  const props: UploadProps = {
    name: 'file',
    multiple: true,
    action: 'https://run.mocky.io/v3/435ba68c-f2a8-4945-8ad8-401574f3c418', // Mock upload URL
    onChange(info) {
      const { status } = info.file;
      if (status === 'done') {
        message.success(`${info.file.name} 上传成功.`);
        // Add to list
        const newFile: DataFile = {
          key: Date.now().toString(),
          name: info.file.name,
          type: info.file.name.split('.').pop()?.toUpperCase() || 'Unknown',
          size: (info.file.size ? (info.file.size / 1024).toFixed(1) + ' KB' : 'Unknown'),
          source: 'Local',
          status: 'Active',
          date: new Date().toLocaleDateString()
        };
        setDataFiles(prev => [...prev, newFile]);
      } else if (status === 'error') {
        message.error(`${info.file.name} 上传失败.`);
      }
    },
    onDrop(e) {
      console.log('Dropped files', e.dataTransfer.files);
    },
  };

  const handleAddUrl = () => {
    if (!urlInput) return;
    const newFile: DataFile = {
      key: Date.now().toString(),
      name: urlInput.split('/').pop() || 'Remote Resource',
      type: 'API',
      size: '-',
      source: 'URL',
      status: 'Active',
      date: new Date().toLocaleDateString()
    };
    setDataFiles(prev => [...prev, newFile]);
    setIsModalOpen(false);
    setUrlInput('');
    message.success('外部数据源添加成功');
  };

  const columns = [
    {
      title: '文件名',
      dataIndex: 'name',
      key: 'name',
      render: (text: string) => <Space><FileTextOutlined /> {text}</Space>,
    },
    {
      title: '类型',
      dataIndex: 'type',
      key: 'type',
      render: (type: string) => <Tag color={type === 'CSV' ? 'blue' : 'green'}>{type}</Tag>,
    },
    {
      title: '大小',
      dataIndex: 'size',
      key: 'size',
    },
    {
      title: '来源',
      dataIndex: 'source',
      key: 'source',
    },
    {
      title: '上传日期',
      dataIndex: 'date',
      key: 'date',
    },
    {
      title: '操作',
      key: 'action',
      render: (_: any, record: DataFile) => (
        <Space size="middle">
          <Button type="text" danger icon={<DeleteOutlined />} onClick={() => {
            setDataFiles(dataFiles.filter(item => item.key !== record.key));
            message.success('文件已删除');
          }}>删除</Button>
        </Space>
      ),
    },
  ];

  return (
    <div className="p-4">
      <h2 className="text-2xl font-bold mb-6">气象数据源管理</h2>
      
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
        <Card className="col-span-2 shadow-sm" title="本地文件上传">
          <Dragger {...props} style={{ height: '200px' }}>
            <p className="ant-upload-drag-icon">
              <InboxOutlined />
            </p>
            <p className="ant-upload-text">点击或拖拽文件到此区域上传</p>
            <p className="ant-upload-hint">
              支持 CSV, Excel, JSON 等常见气象数据格式。
            </p>
          </Dragger>
        </Card>

        <Card className="shadow-sm" title="外部数据源配置">
          <div className="flex flex-col justify-center h-full items-center">
            <LinkOutlined style={{ fontSize: '48px', color: '#1677ff', marginBottom: '16px' }} />
            <p className="text-gray-500 mb-4 text-center">连接到远程 API 或在线数据文件</p>
            <Button type="primary" onClick={() => setIsModalOpen(true)}>添加 URL 资源</Button>
          </div>
        </Card>
      </div>

      <Card title="已配置数据列表" className="shadow-sm">
        <Table columns={columns} dataSource={dataFiles} />
      </Card>

      <Modal title="添加外部数据源 URL" open={isModalOpen} onOk={handleAddUrl} onCancel={() => setIsModalOpen(false)}>
        <Input 
          placeholder="请输入数据源 URL (例如: https://api.weather.com/v1/...)" 
          value={urlInput}
          onChange={e => setUrlInput(e.target.value)}
        />
      </Modal>
    </div>
  );
};

export default DataManagement;
