import React, { useState, useEffect } from 'react';
import { Card, Slider, Select, Row, Col, Typography, Progress, Statistic, Alert } from 'antd';
import { SunOutlined, CloudOutlined, CloudDownloadOutlined, ExperimentOutlined } from '@ant-design/icons';
import ReactECharts from 'echarts-for-react';

const { Title, Text } = Typography;
const { Option } = Select;

const Agriculture: React.FC = () => {
  const [crop, setCrop] = useState('peach');
  const [temperature, setTemperature] = useState(25);
  const [sunlight, setSunlight] = useState(80);
  const [precipitation, setPrecipitation] = useState(50);
  const [growthStatus, setGrowthStatus] = useState({
    health: 100,
    yield: 100,
    stage: 'Mature',
    description: '生长状况良好，预计丰收。'
  });

  useEffect(() => {
    // Simple simulation logic
    let health = 100;
    let yield_val = 100;
    let description = '生长状况良好，预计丰收。';

    // Temperature Logic (Peach ideal: 18-30)
    if (temperature < 10 || temperature > 35) {
      health -= 30;
      yield_val -= 40;
      description = temperature < 10 ? '温度过低，作物生长受阻，可能有冻害。' : '温度过高，作物水分蒸发快，影响果实品质。';
    } else if (temperature < 18 || temperature > 30) {
      health -= 10;
      yield_val -= 10;
      description = '温度略有偏差，生长速度减缓。';
    }

    // Sunlight Logic (Ideal: > 60)
    if (sunlight < 40) {
      health -= 20;
      yield_val -= 30;
      description += ' 光照不足，果实糖分积累不够，色泽差。';
    }

    // Precipitation Logic (Ideal: 30-70)
    if (precipitation < 20) {
      health -= 20;
      yield_val -= 20;
      description += ' 降水不足，需及时灌溉。';
    } else if (precipitation > 80) {
      health -= 15;
      yield_val -= 25;
      description += ' 降水过多，注意排水防涝。';
    }

    setGrowthStatus({
      health: Math.max(0, health),
      yield: Math.max(0, yield_val),
      stage: health > 80 ? '丰产期' : health > 50 ? '生长期' : '受灾期',
      description
    });
  }, [temperature, sunlight, precipitation, crop]);

  const getCropIcon = () => {
    // Simple visual representation using emojis based on health
    const count = Math.ceil(growthStatus.yield / 10);
    const icon = crop === 'peach' ? '🍑' : '🌾';
    const deadIcon = '🥀';
    
    if (growthStatus.health < 30) return Array(5).fill(deadIcon).join(' ');

    let icons = [];
    for(let i=0; i<count; i++) {
      icons.push(<span key={i} style={{fontSize: '24px', opacity: sunlight/100, filter: `grayscale(${100-growthStatus.health}%)`}}>{icon}</span>);
    }
    return <div className="flex flex-wrap gap-2">{icons}</div>;
  };

  const getChartOption = () => {
    return {
      title: { text: '生长环境综合评分' },
      radar: {
        indicator: [
          { name: '温度适宜度', max: 100 },
          { name: '光照充足度', max: 100 },
          { name: '水分适宜度', max: 100 },
          { name: '土壤肥力(模拟)', max: 100 },
          { name: '病虫害风险(逆)', max: 100 }
        ]
      },
      series: [{
        name: '环境评分',
        type: 'radar',
        data: [{
          value: [
            100 - Math.abs(temperature - 25) * 3,
            sunlight,
            100 - Math.abs(precipitation - 50) * 1.5,
            85,
            Math.max(20, 100 - humidityRisk()) 
          ],
          name: '当前环境'
        }]
      }]
    };
  };

  const humidityRisk = () => {
    // High temp + high precip = high pest risk
    if (temperature > 25 && precipitation > 70) return 80;
    return 30;
  };

  const getMapOption = () => {
    // Mock map data for tech-style visualization
    return {
      backgroundColor: '#100c2a',
      title: {
        text: '金华市农业气象监测网',
        left: 'center',
        textStyle: { color: '#fff' }
      },
      geo: {
        map: 'jinhua', // Ensure 'jinhua' map is registered (reuse from Visualization2D logic or register here if needed)
        roam: true,
        label: { show: false },
        itemStyle: {
          areaColor: '#323c48',
          borderColor: '#404a59'
        },
        emphasis: {
          itemStyle: { areaColor: '#2a333d' }
        }
      },
      series: [
        {
          name: '监测点',
          type: 'effectScatter',
          coordinateSystem: 'geo',
          data: [
            { name: '婺城区', value: [119.64, 29.07, 80] },
            { name: '金东区', value: [119.69, 29.09, 90] },
            { name: '兰溪市', value: [119.46, 29.21, 70] },
            { name: '义乌市', value: [120.07, 29.30, 85] }
          ],
          symbolSize: 15,
          showEffectOn: 'render',
          rippleEffect: {
            brushType: 'stroke'
          },
          label: {
            formatter: '{b}',
            position: 'right',
            show: true
          },
          itemStyle: {
            color: '#f4e925',
            shadowBlur: 10,
            shadowColor: '#333'
          }
        }
      ]
    };
  };

  return (
    <div className="p-4">
      <Title level={2}><ExperimentOutlined /> 农业气象生长模拟</Title>
      
      <Row gutter={24}>
        <Col span={8}>
          <Card title="环境条件设置" className="mb-4 shadow-sm">
            <div className="mb-6">
              <Text strong><SunOutlined /> 温度 (°C)</Text>
              <Slider min={-10} max={45} value={temperature} onChange={setTemperature} marks={{0: '0°C', 25: '25°C', 40: '40°C'}} />
            </div>
            <div className="mb-6">
              <Text strong><SunOutlined /> 光照强度 (%)</Text>
              <Slider min={0} max={100} value={sunlight} onChange={setSunlight} />
            </div>
            <div className="mb-6">
              <Text strong><CloudDownloadOutlined /> 降水量 (mm)</Text>
              <Slider min={0} max={150} value={precipitation} onChange={setPrecipitation} />
            </div>
            <div className="mb-4">
              <Text strong>作物选择</Text>
              <Select value={crop} style={{ width: '100%' }} onChange={setCrop}>
                <Option value="peach">金华水蜜桃</Option>
                <Option value="rice">水稻</Option>
                <Option value="tea">茶叶</Option>
              </Select>
            </div>
          </Card>

          <Card title="环境分析" className="shadow-sm">
            <ReactECharts option={getChartOption()} style={{height: '300px'}} />
          </Card>
        </Col>

        <Col span={16}>
          <Card className="mb-4 shadow-sm" style={{ background: '#000', padding: 0 }} bodyStyle={{ padding: 0 }}>
             {/* Tech-style Map */}
             <ReactECharts option={getMapOption()} style={{height: '400px', width: '100%'}} />
          </Card>

          <Card title="作物生长状态模拟" className="mb-4 shadow-sm" style={{minHeight: '600px'}}>
            <Row gutter={16} className="mb-8">
              <Col span={8}>
                <Statistic title="预计产量" value={growthStatus.yield} suffix="%" valueStyle={{ color: growthStatus.yield > 80 ? '#3f8600' : '#cf1322' }} />
                <Progress percent={growthStatus.yield} status={growthStatus.yield > 80 ? 'success' : 'exception'} showInfo={false} />
              </Col>
              <Col span={8}>
                <Statistic title="健康指数" value={growthStatus.health} suffix="/ 100" valueStyle={{ color: growthStatus.health > 80 ? '#3f8600' : '#cf1322' }} />
                <Progress percent={growthStatus.health} status={growthStatus.health > 80 ? 'active' : 'exception'} showInfo={false} />
              </Col>
              <Col span={8}>
                <Statistic title="生长阶段" value={growthStatus.stage} />
              </Col>
            </Row>

            <Alert 
              message="农情分析报告" 
              description={growthStatus.description} 
              type={growthStatus.health > 70 ? "success" : "warning"} 
              showIcon 
              className="mb-8"
            />

            <div className="bg-green-50 p-8 rounded-lg border border-green-100 min-h-[300px] relative overflow-hidden">
               {/* Background simulation based on weather */}
               <div className="absolute inset-0 pointer-events-none" style={{
                 background: sunlight < 50 ? 'rgba(0,0,0,0.3)' : 'transparent',
                 zIndex: 0
               }} />
               {precipitation > 60 && (
                 <div className="absolute inset-0 pointer-events-none z-10" style={{
                   backgroundImage: 'linear-gradient(to bottom, rgba(255,255,255,0) 0%, rgba(255,255,255,0.5) 100%)',
                   opacity: 0.5
                 }}>
                   {/* Rain animation could go here */}
                   <div className="text-center text-blue-400 mt-10">🌧️ 正在降雨...</div>
                 </div>
               )}

               <div className="relative z-20">
                 <Title level={4} className="mb-4 text-center">作物形态模拟展示</Title>
                 <div className="flex justify-center items-end h-[200px] flex-wrap content-end">
                   {getCropIcon()}
                 </div>
               </div>
            </div>
          </Card>
        </Col>
      </Row>
    </div>
  );
};

export default Agriculture;
